    // --- Context + execute bindings ---
    nb::class_<veda64::ir::Context>(ir_mod, "Context")
        .def(nb::init<>())
        .def("get_gpr", [](const veda64::ir::Context& c, int reg) -> uint64_t {
            if (reg < 0 || reg > 31) return 0;
            return c.gpr[reg];
        }, "reg"_a)
        .def("set_gpr", [](veda64::ir::Context& c, int reg, uint64_t val) {
            if (reg >= 0 && reg <= 31) c.gpr[reg] = val;
        }, "reg"_a, "val"_a)
        .def("get_flag", [](const veda64::ir::Context& c, int idx) -> int {
            if (idx < 0 || idx > 3) return 0;
            return c.flags[idx];
        }, "idx"_a)
        .def("set_flag", [](veda64::ir::Context& c, int idx, int val) {
            if (idx >= 0 && idx <= 3) c.flags[idx] = val ? 1 : 0;
        }, "idx"_a, "val"_a)
        .def_rw("pc", &veda64::ir::Context::pc)
        .def_rw("halted", &veda64::ir::Context::halted)
        ;

    ir_mod.def("execute", [](veda64::ir::Context& ctx, uint32_t insn) {
        if (!ctx.memory) {
            static std::vector<uint8_t> default_mem(65536, 0);
            ctx.memory = default_mem.data();
            ctx.memory_size = default_mem.size();
        }
        veda64::ir::execute(ctx, insn);
    }, "ctx"_a, "insn"_a, "Execute a single ARM64 instruction against a context");

#endif // VEDA64_IR

    // --- Relocation API bindings ---
    m.def("is_pc_relative", &veda64::is_pc_relative, "insn"_a,
        "Check if an instruction is PC-relative");
    m.def("can_relocate", &veda64::can_relocate, "insn"_a,
        "Check if an instruction can be safely relocated");
    m.def("relocate_instruction", [](uint32_t insn, uint64_t old_pc, uint64_t new_pc) {
        uint32_t out[4];
        size_t count = 0;
        bool ok = veda64::relocate_instruction(insn, old_pc, new_pc, out, &count);
        nb::list result;
        if (ok) { for (size_t i = 0; i < count; i++) result.append(out[i]); }
        return nb::make_tuple(ok, result);
    }, "insn"_a, "old_pc"_a, "new_pc"_a,
        "Relocate an instruction from old_pc to new_pc. Returns (success, [relocated_insns])");

